styles:
.reader-quote {
  font-style: normal;
  color: var(--reader-accent-start, #667eea);
  border-bottom: 1px solid rgba(102, 126, 234, 0.3);
  padding-bottom: 1px;
}
.reader-ellipsis {
  letter-spacing: 4px;
  opacity: 0.5;
}
.reader-dash {
  letter-spacing: 3px;
  opacity: 0.6;
}
.reader-speak {
  color: var(--reader-strong, #aaa);
  font-weight: 600;
}
